mkitem!{mktrait!{# [doc = " Lossy `as` casting between two types."] pub trait CastInto < T : Copy > : Copy { fn cast (self) -> T ; }}}
mkitem!{mktrait!{# [doc = " Collection of traits that allow us to be generic over integer size."] pub trait Integer : Sized + Clone + Copy + Debug + ops :: Shr < u32 , Output = Self > + ops :: Shl < u32 , Output = Self > + ops :: BitAnd < Output = Self > + ops :: BitOr < Output = Self > + PartialEq + CastInto < i16 > { const ZERO : Self ; const ONE : Self ; }}}
mkitem!{macro_rules ! int { ($ ($ ty : ty) ,+) => { $ (impl CastInto < i16 > for $ ty { fn cast (self) -> i16 { self as i16 } } impl Integer for $ ty { const ZERO : Self = 0 ; const ONE : Self = 1 ; }) + } }}
mkitem!{int ! (u16 , u32 , u64) ;}
mkitem!{mktrait!{# [doc = " A helper trait to avoid duplicating basically all the conversion code for IEEE floats."] # [doc = ""] # [doc = " See the parent module's doc comment for why this is necessary."] # [doc = ""] # [doc = " Should **never ever** be implemented for other types or be used outside the `dec2flt` module."] # [doc (hidden)] pub trait RawFloat : Sized + Div < Output = Self > + Neg < Output = Self > + Mul < Output = Self > + Add < Output = Self > + LowerExp + PartialEq + PartialOrd + Default + Clone + Copy + Debug { # [doc = " The unsigned integer with the same size as the float"] type Int : Integer + Into < u64 > ; const INFINITY : Self ; const NEG_INFINITY : Self ; const NAN : Self ; const NEG_NAN : Self ; # [doc = " Bit width of the float"] const BITS : u32 ; # [doc = " The number of bits in the significand, *including* the hidden bit."] const SIG_TOTAL_BITS : u32 ; const EXP_MASK : Self :: Int ; const SIG_MASK : Self :: Int ; # [doc = " The number of bits in the significand, *excluding* the hidden bit."] const SIG_BITS : u32 = Self :: SIG_TOTAL_BITS - 1 ; # [doc = " Number of bits in the exponent."] const EXP_BITS : u32 = Self :: BITS - Self :: SIG_BITS - 1 ; # [doc = " The saturated (maximum bitpattern) value of the exponent, i.e. the infinite"] # [doc = " representation."] # [doc = ""] # [doc = " This shifted fully right, use `EXP_MASK` for the shifted value."] const EXP_SAT : u32 = (1 << Self :: EXP_BITS) - 1 ; # [doc = " Signed version of `EXP_SAT` since we convert a lot."] const INFINITE_POWER : i32 = Self :: EXP_SAT as i32 ; # [doc = " The exponent bias value. This is also the maximum value of the exponent."] const EXP_BIAS : u32 = Self :: EXP_SAT >> 1 ; # [doc = " Minimum exponent value of normal values."] const EXP_MIN : i32 = - (Self :: EXP_BIAS as i32 - 1) ; # [doc = " Round-to-even only happens for negative values of q"] # [doc = " when q ≥ −4 in the 64-bit case and when q ≥ −17 in"] # [doc = " the 32-bit case."] # [doc = ""] # [doc = " When q ≥ 0,we have that 5^q ≤ 2m+1. In the 64-bit case,we"] # [doc = " have 5^q ≤ 2m+1 ≤ 2^54 or q ≤ 23. In the 32-bit case,we have"] # [doc = " 5^q ≤ 2m+1 ≤ 2^25 or q ≤ 10."] # [doc = ""] # [doc = " When q < 0, we have w ≥ (2m+1)×5^−q. We must have that w < 2^64"] # [doc = " so (2m+1)×5^−q < 2^64. We have that 2m+1 > 2^53 (64-bit case)"] # [doc = " or 2m+1 > 2^24 (32-bit case). Hence,we must have 2^53×5^−q < 2^64"] # [doc = " (64-bit) and 2^24×5^−q < 2^64 (32-bit). Hence we have 5^−q < 2^11"] # [doc = " or q ≥ −4 (64-bit case) and 5^−q < 2^40 or q ≥ −17 (32-bit case)."] # [doc = ""] # [doc = " Thus we have that we only need to round ties to even when"] # [doc = " we have that q ∈ [−4,23](in the 64-bit case) or q∈[−17,10]"] # [doc = " (in the 32-bit case). In both cases,the power of five(5^|q|)"] # [doc = " fits in a 64-bit word."] const MIN_EXPONENT_ROUND_TO_EVEN : i32 ; const MAX_EXPONENT_ROUND_TO_EVEN : i32 ; # [doc = " Largest decimal exponent for a non-infinite value."] # [doc = ""] # [doc = " This is the max exponent in binary converted to the max exponent in decimal. Allows fast"] # [doc = " pathing anything larger than `10^LARGEST_POWER_OF_TEN`, which will round to infinity."] const LARGEST_POWER_OF_TEN : i32 = { let largest_pow2 = Self :: EXP_BIAS + 1 ; pow2_to_pow10 (largest_pow2 as i64) as i32 } ; # [doc = " Smallest decimal exponent for a non-zero value. This allows for fast pathing anything"] # [doc = " smaller than `10^SMALLEST_POWER_OF_TEN`, which will round to zero."] # [doc = ""] # [doc = " The smallest power of ten is represented by `⌊log10(2^-n / (2^64 - 1))⌋`, where `n` is"] # [doc = " the smallest power of two. The `2^64 - 1)` denominator comes from the number of values"] # [doc = " that are representable by the intermediate storage format. I don't actually know _why_"] # [doc = " the storage format is relevant here."] # [doc = ""] # [doc = " The values may be calculated using the formula. Unfortunately we cannot calculate them at"] # [doc = " compile time since intermediates exceed the range of an `f64`."] const SMALLEST_POWER_OF_TEN : i32 ; # [doc = " Maximum exponent for a fast path case, or `⌊(SIG_BITS+1)/log2(5)⌋`"] const MAX_EXPONENT_FAST_PATH : i64 = { let log2_5 = f64 :: consts :: LOG2_10 - 1.0 ; (Self :: SIG_TOTAL_BITS as f64 / log2_5) as i64 } ; # [doc = " Minimum exponent for a fast path case, or `-⌊(SIG_BITS+1)/log2(5)⌋`"] const MIN_EXPONENT_FAST_PATH : i64 = - Self :: MAX_EXPONENT_FAST_PATH ; # [doc = " Maximum exponent that can be represented for a disguised-fast path case."] # [doc = " This is `MAX_EXPONENT_FAST_PATH + ⌊(SIG_BITS+1)/log2(10)⌋`"] const MAX_EXPONENT_DISGUISED_FAST_PATH : i64 = Self :: MAX_EXPONENT_FAST_PATH + (Self :: SIG_TOTAL_BITS as f64 / f64 :: consts :: LOG2_10) as i64 ; # [doc = " Maximum mantissa for the fast-path (`1 << 53` for f64)."] const MAX_MANTISSA_FAST_PATH : u64 = 1 << Self :: SIG_TOTAL_BITS ; # [doc = " Converts integer into float through an as cast."] # [doc = " This is only called in the fast-path algorithm, and therefore"] # [doc = " will not lose precision, since the value will always have"] # [doc = " only if the value is <= Self::MAX_MANTISSA_FAST_PATH."] fn from_u64 (v : u64) -> Self ; # [doc = " Performs a raw transmutation from an integer."] fn from_u64_bits (v : u64) -> Self ; # [doc = " Gets a small power-of-ten for fast-path multiplication."] fn pow10_fast_path (exponent : usize) -> Self ; # [doc = " Returns the category that this number falls into."] fn classify (self) -> FpCategory ; # [doc = " Transmute to the integer representation"] fn to_bits (self) -> Self :: Int ; # [doc = " Returns the mantissa, exponent and sign as integers."] # [doc = ""] # [doc = " This returns `(m, p, s)` such that `s * m * 2^p` represents the original float. For 0, the"] # [doc = " exponent will be `-(EXP_BIAS + SIG_BITS)`, which is the minimum subnormal power. For"] # [doc = " infinity or NaN, the exponent will be `EXP_SAT - EXP_BIAS - SIG_BITS`."] # [doc = ""] # [doc = " If subnormal, the mantissa will be shifted one bit to the left. Otherwise, it is returned"] # [doc = " with the explicit bit set but otherwise unshifted"] # [doc = ""] # [doc = " `s` is only ever +/-1."] fn integer_decode (self) -> (u64 , i16 , i8) { let bits = self . to_bits () ; let sign : i8 = if bits >> (Self :: BITS - 1) == Self :: Int :: ZERO { 1 } else { - 1 } ; let mut exponent : i16 = ((bits & Self :: EXP_MASK) >> Self :: SIG_BITS) . cast () ; let mantissa = if exponent == 0 { (bits & Self :: SIG_MASK) << 1 } else { (bits & Self :: SIG_MASK) | (Self :: Int :: ONE << Self :: SIG_BITS) } ; exponent -= (Self :: EXP_BIAS + Self :: SIG_BITS) as i16 ; (mantissa . into () , exponent , sign) } }}}

macro_rules! pow2_to_pow10_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function pow2_to_pow10 in module {}", module_path!());
    };
}

mkfn!{
    pow2_to_pow10_introspect!();
    # [doc = " Solve for `b` in `10^b = 2^a`"] const fn pow2_to_pow10 (a : i64) -> i64 { let res = (a as f64) / f64 :: consts :: LOG2_10 ; res as i64 }
}
mkitem!{mkimpl!{# [cfg (target_has_reliable_f16)] impl RawFloat for f16 { type Int = u16 ; const INFINITY : Self = Self :: INFINITY ; const NEG_INFINITY : Self = Self :: NEG_INFINITY ; const NAN : Self = Self :: NAN ; const NEG_NAN : Self = - Self :: NAN ; const BITS : u32 = 16 ; const SIG_TOTAL_BITS : u32 = Self :: MANTISSA_DIGITS ; const EXP_MASK : Self :: Int = Self :: EXP_MASK ; const SIG_MASK : Self :: Int = Self :: MAN_MASK ; const MIN_EXPONENT_ROUND_TO_EVEN : i32 = - 22 ; const MAX_EXPONENT_ROUND_TO_EVEN : i32 = 5 ; const SMALLEST_POWER_OF_TEN : i32 = - 27 ; # [inline] fn from_u64 (v : u64) -> Self { debug_assert ! (v <= Self :: MAX_MANTISSA_FAST_PATH) ; v as _ } # [inline] fn from_u64_bits (v : u64) -> Self { Self :: from_bits ((v & 0xFFFF) as u16) } fn pow10_fast_path (exponent : usize) -> Self { # [allow (clippy :: use_self)] const TABLE : [f16 ; 8] = [1e0 , 1e1 , 1e2 , 1e3 , 1e4 , 0.0 , 0.0 , 0.] ; TABLE [exponent & 7] } fn to_bits (self) -> Self :: Int { self . to_bits () } fn classify (self) -> FpCategory { self . classify () } }}}
mkitem!{mkimpl!{impl RawFloat for f32 { type Int = u32 ; const INFINITY : Self = f32 :: INFINITY ; const NEG_INFINITY : Self = f32 :: NEG_INFINITY ; const NAN : Self = f32 :: NAN ; const NEG_NAN : Self = - f32 :: NAN ; const BITS : u32 = 32 ; const SIG_TOTAL_BITS : u32 = Self :: MANTISSA_DIGITS ; const EXP_MASK : Self :: Int = Self :: EXP_MASK ; const SIG_MASK : Self :: Int = Self :: MAN_MASK ; const MIN_EXPONENT_ROUND_TO_EVEN : i32 = - 17 ; const MAX_EXPONENT_ROUND_TO_EVEN : i32 = 10 ; const SMALLEST_POWER_OF_TEN : i32 = - 65 ; # [inline] fn from_u64 (v : u64) -> Self { debug_assert ! (v <= Self :: MAX_MANTISSA_FAST_PATH) ; v as _ } # [inline] fn from_u64_bits (v : u64) -> Self { f32 :: from_bits ((v & 0xFFFFFFFF) as u32) } fn pow10_fast_path (exponent : usize) -> Self { # [allow (clippy :: use_self)] const TABLE : [f32 ; 16] = [1e0 , 1e1 , 1e2 , 1e3 , 1e4 , 1e5 , 1e6 , 1e7 , 1e8 , 1e9 , 1e10 , 0. , 0. , 0. , 0. , 0.] ; TABLE [exponent & 15] } fn to_bits (self) -> Self :: Int { self . to_bits () } fn classify (self) -> FpCategory { self . classify () } }}}
mkitem!{mkimpl!{impl RawFloat for f64 { type Int = u64 ; const INFINITY : Self = Self :: INFINITY ; const NEG_INFINITY : Self = Self :: NEG_INFINITY ; const NAN : Self = Self :: NAN ; const NEG_NAN : Self = - Self :: NAN ; const BITS : u32 = 64 ; const SIG_TOTAL_BITS : u32 = Self :: MANTISSA_DIGITS ; const EXP_MASK : Self :: Int = Self :: EXP_MASK ; const SIG_MASK : Self :: Int = Self :: MAN_MASK ; const MIN_EXPONENT_ROUND_TO_EVEN : i32 = - 4 ; const MAX_EXPONENT_ROUND_TO_EVEN : i32 = 23 ; const SMALLEST_POWER_OF_TEN : i32 = - 342 ; # [inline] fn from_u64 (v : u64) -> Self { debug_assert ! (v <= Self :: MAX_MANTISSA_FAST_PATH) ; v as _ } # [inline] fn from_u64_bits (v : u64) -> Self { f64 :: from_bits (v) } fn pow10_fast_path (exponent : usize) -> Self { const TABLE : [f64 ; 32] = [1e0 , 1e1 , 1e2 , 1e3 , 1e4 , 1e5 , 1e6 , 1e7 , 1e8 , 1e9 , 1e10 , 1e11 , 1e12 , 1e13 , 1e14 , 1e15 , 1e16 , 1e17 , 1e18 , 1e19 , 1e20 , 1e21 , 1e22 , 0. , 0. , 0. , 0. , 0. , 0. , 0. , 0. , 0. ,] ; TABLE [exponent & 31] } fn to_bits (self) -> Self :: Int { self . to_bits () } fn classify (self) -> FpCategory { self . classify () } }}}